/**
 * 易經學院課程內容(Phase 2)。
 * 全部為本站原創白話講解(zht);古典經文引文為公有領域,未引用任何現代注本。
 * zhs/en 暫回落 zht(見 yjT 的回落邏輯)。
 */

export interface AcademyQuizQ {
  q: string;
  options: [string, string, string, string];
  /** 正確答案索引 0–3 */
  answer: number;
  explain: string;
}

export interface AcademySection {
  heading: string;
  body: string[];
}

/** 課程出處:已親自抓取核實過的公有領域原文鏈接(勿憑空編造 URL)。 */
export interface AcademySource {
  label: string;
  url: string;
}

/**
 * 古典引文參照(證據鏈):課文引用的古籍原文,點按彈出全文 + 出處。
 * - quote: 課文所引短句(與正文標點一致)。
 * - fullText: 較完整的原文段落,逐字核實自 zh.wikisource.org 公有領域文本
 *   (2026-10-23 親自抓取;无→無 按本站公版通行本體例統一,屬字形變體非改字)。
 * - url: 已親自抓取核實,勿憑空編造。
 */
export interface AcademyQuoteRef {
  /** 唯一 id */
  id: string;
  /** 短引文(課文所引) */
  quote: string;
  /** 較完整的原文段落(1–4 句) */
  fullText: string;
  /** 出處標籤,如《繫辭上·第五章》 */
  sourceLabel: string;
  /** 已核實的公有領域原文鏈接 */
  url: string;
}

