        "書中進一步指出：若家中與某人對應的宮位缺角，那一宮的能量先天不足；宮位有煞衝射，也同樣令人待不住。缺角與煞，在本書的語言裡都是『失衡』的具體形態，與前文以五為平衡的標準一脈相承：不是詛咒，而是某個位置的條件明顯偏離中位。不過作者在章末特意補上一句分寸：風水是外援，努力才是根本——猶如學外語再重要，也不能因此荒廢母語與數理。把環境調順，是為了讓人的努力有一個安頓的基地，而不是代替努力本身。",
