        "書中青牛師父有一段自白很能代表這種態度：他不會固執地認為自己的就是對的、別人的都是錯的；遇有實戰案例，不妨一起探討，讓流傳下來零落的文化更加完善。對初學者而言，這比任何具體結論都重要——風水的知識是在驗證與討論中長成的，不是在背誦中定型的。",
