        "爭議最大的，是筆畫數一路。它流傳最廣——坊間的姓名打分多以此為骨幹——卻也最經不起追問。原因是筆畫定五行並非只有一套標準：通行者至少有兩系，兩系之間互相矛盾；同一系之內，又有大量特殊規定與例外。下一節把兩系並陳，並把書中指出的破綻逐一擺明，學員看完，自會明白書中『兼顧即可』四字的分量。",
